{
  "name": "安捷伦E44xx频谱分析仪",
  "name_en": "Agilent E44xx Spectrum Analyzer",
  "manufacturer": "Agilent",
  "description": "这是一类用于测量射频和微波信号频谱的台式频谱分析仪，可对信号的频率分布、功率电平和带宽特性进行分析。实验中常用于信号源表征、杂散与谐波测试、带宽测量、频谱监测以及一般射频链路调试。",
  "description_en": "This is a benchtop spectrum analyzer for measuring the spectral content of RF and microwave signals. It is commonly used in laboratories for signal source characterization, spurious and harmonic measurements, bandwidth analysis, spectrum monitoring, and general RF chain debugging.",
  "tag_hints": [
    "spectrum analyzer",
    "RF measurement",
    "microwave test",
    "frequency sweep",
    "RBW/VBW control",
    "trace acquisition",
    "spurious and harmonic analysis"
  ],
  "actions": [
    {
      "action_name": "auto-select",
      "description": "选择测量或仪器工作模式。",
      "description_en": "Select the measurement or instrument operating mode."
    },
    {
      "action_name": "auto-frequency",
      "description": "获取或设置测量频率。",
      "description_en": "Get or set the measurement frequency."
    },
    {
      "action_name": "auto-frequency_center",
      "description": "获取或设置中心频率。",
      "description_en": "Get or set the center frequency."
    },
    {
      "action_name": "auto-frequency_span",
      "description": "获取或设置频率跨度。",
      "description_en": "Get or set the frequency span."
    },
    {
      "action_name": "auto-frequency_start",
      "description": "获取或设置起始频率。",
      "description_en": "Get or set the start frequency."
    },
    {
      "action_name": "auto-frequency_stop",
      "description": "获取或设置终止频率。",
      "description_en": "Get or set the stop frequency."
    },
    {
      "action_name": "auto-sweep_points",
      "description": "获取或设置扫频点数。",
      "description_en": "Get or set the number of sweep points."
    },
    {
      "action_name": "auto-sweep_points_max",
      "description": "获取最大扫频点数。",
      "description_en": "Get the maximum number of sweep points."
    },
    {
      "action_name": "auto-view_range",
      "description": "获取显示范围。",
      "description_en": "Get the display range."
    },
    {
      "action_name": "auto-sweep_time",
      "description": "获取或设置扫频时间。",
      "description_en": "Get or set the sweep time."
    },
    {
      "action_name": "auto-reference_level",
      "description": "获取或设置参考电平。",
      "description_en": "Get or set the reference level."
    },
    {
      "action_name": "auto-resolution_bandwidths",
      "description": "获取可用的分辨率带宽列表。",
      "description_en": "Get the list of available resolution bandwidths."
    },
    {
      "action_name": "auto-resolution_bandwidth",
      "description": "获取或设置分辨率带宽。",
      "description_en": "Get or set the resolution bandwidth."
    },
    {
      "action_name": "auto-video_bandwidth",
      "description": "获取或设置视频带宽。",
      "description_en": "Get or set the video bandwidth."
    },
    {
      "action_name": "auto-unit_power",
      "description": "获取或设置功率单位。",
      "description_en": "Get or set the power unit."
    },
    {
      "action_name": "auto-detector",
      "description": "获取或设置检波方式。",
      "description_en": "Get or set the detector mode."
    },
    {
      "action_name": "auto-input_attenuator",
      "description": "获取或设置输入衰减。",
      "description_en": "Get or set the input attenuation."
    },
    {
      "action_name": "auto-continuous",
      "description": "获取或设置连续扫频状态。",
      "description_en": "Get or set the continuous sweep state."
    },
    {
      "action_name": "auto-input_attenuator_auto",
      "description": "获取或设置输入衰减自动模式。",
      "description_en": "Get or set the automatic input attenuation mode."
    },
    {
      "action_name": "auto-trace_type",
      "description": "获取或设置迹线类型。",
      "description_en": "Get or set the trace type."
    },
    {
      "action_name": "auto-external_gain",
      "description": "获取或设置外部增益修正。",
      "description_en": "Get or set the external gain correction."
    },
    {
      "action_name": "auto-trace_data",
      "description": "读取当前迹线数据。",
      "description_en": "Read the current trace data."
    },
    {
      "action_name": "auto-screenshot",
      "description": "采集屏幕截图。",
      "description_en": "Capture a screenshot."
    },
    {
      "action_name": "auto-trace",
      "description": "读取当前测量迹线。",
      "description_en": "Read the current measurement trace."
    },
    {
      "action_name": "auto-trace_sa",
      "description": "读取频谱分析模式下的迹线及相关测量信息。",
      "description_en": "Read the trace and related measurement information in spectrum analysis mode."
    }
  ]
}

